/* empty space where another skill of the chain has "Effect Granted" (same height as the real thing) */
.aa-skill-reserve {
  visibility: hidden;
}
/* shown in the kept space of a skill without effects, when another skill of its chain has some */
.aa-skill-noeffects {
  color: #6f6a5e;
  font-style: italic;
}
.aa-skill-buffspace {
  height: 34px;
  margin-top: 4px;
}
/* the free space of a stretched card goes above the Chain row, which sits at the bottom of the card */
.aa-skill-chainbox {
  margin-top: auto;
}
/* margins of a column do not collapse: the header's bottom margin and the line's top margin would add up */
.aa-varset > .aa-skill .aa-skill-head {
  margin-bottom: 0;
}
.aa-skill {
  display: flow-root;
  position: relative;
  box-sizing: border-box;
  width: 320px;
  max-width: 100%;
  padding: 10px 12px;
  background: linear-gradient(to bottom, rgba(24, 28, 38, 0.97), rgba(10, 12, 18, 0.97));
  border: 1px solid #5a5040;
  border-radius: 3px;
  box-shadow: 0 0 0 1px #000, 0 4px 12px rgba(0, 0, 0, 0.6);
  margin: 0 0 0.5em 0;
  color: #e8e4d8;
  font-size: 13px;
  line-height: 1.5;
  text-align: left;
}
.aa-skill-head {
  display: flex;
  gap: 10px;
  align-items: center;
  margin-bottom: 6px;
}
.aa-skill-icon {
  line-height: 0;
  border: 1px solid #000;
}
.aa-skill-title {
  display: flex;
  flex-direction: column;
  line-height: 1.3;
}
/* skill line (Songcraft ...) in the orange of the game */
.aa-skill-line {
  color: #ff9c27;
}
.aa-skill-name {
  font-size: 16px;
  font-weight: bold;
  color: #ffffff;
}
.aa-skill-sep {
  height: 1px;
  margin: 6px 0;
  background: linear-gradient(to right, transparent, #6a5d48, transparent);
}
.aa-skill-meta {
  color: #c9c3b4;
}
.aa-skill-buffs {
  margin-top: 4px;
  line-height: 0;
}
/* green frame around the icon of an effect; hovering it opens a box with the effect */
.aa-skill-buff {
  position: relative;
  display: inline-block;
  line-height: 0;
  cursor: help;
  outline: none;
  border: 1px solid #4ec24e;
  box-shadow: 0 0 3px rgba(78, 194, 78, 0.6);
}
.aa-skill-bufftip {
  display: none;
  position: absolute;
  left: 0;
  top: 100%;
  z-index: 1000;
  box-sizing: border-box;
  width: 260px;
  margin-top: 4px;
  padding: 7px 9px;
  background: linear-gradient(to bottom, rgba(24, 28, 38, 0.98), rgba(10, 12, 18, 0.98));
  border: 1px solid #5a5040;
  border-radius: 3px;
  box-shadow: 0 0 0 1px #000, 0 4px 12px rgba(0, 0, 0, 0.6);
  color: #d8d2c4;
  font-size: 12px;
  line-height: 1.45;
  text-align: left;
  white-space: normal;
  pointer-events: none;
}
.aa-skill-right .aa-skill-bufftip {
  left: auto;
  right: 0;
}
.aa-skill-buff:hover .aa-skill-bufftip,
.aa-skill-buff:focus .aa-skill-bufftip,
.aa-skill-req:hover .aa-skill-bufftip,
.aa-skill-req:focus .aa-skill-bufftip,
.aa-skill-applier:hover .aa-skill-bufftip,
.aa-skill-applier:focus .aa-skill-bufftip {
  display: block;
}
/* an effect that needs a passive skill: always visible under the icons */
.aa-skill-req {
  position: relative;
  display: flex;
  gap: 6px;
  align-items: center;
  margin-top: 5px;
  color: #ff9c27;
  cursor: help;
  outline: none;
}
.aa-skill-req img {
  display: block;
  border: 1px solid #000;
}
.aa-skill-reqnote {
  display: block;
  margin-bottom: 3px;
  color: #ff9c27;
}
/* the icon of a combo's condition: hovering it lists the skills that apply the effect */
.aa-skill-applier {
  position: relative;
  display: inline-block;
  cursor: help;
  outline: none;
}
.aa-skill-applier .aa-skill-bufftip {
  top: auto;
  bottom: 100%;
  margin: 0 0 4px;
  line-height: 1.45;
}
.aa-skill-applysub.aa-skill-applynote {
  color: #b9b09a;
  font-style: italic;
}
.aa-skill-applyrow {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 3px;
}
.aa-skill-applyrow img {
  display: block;
  border: 1px solid #000;
}
.aa-skill-applyrow .aa-skill-applyitem img {
  border: 0;
}
.aa-skill-applyneed,
.aa-skill-applyicon {
  flex: none;
  line-height: 0;
}
.aa-skill-applyneed img {
  display: block;
  border: 1px solid #d9423a;
  box-shadow: 0 0 3px rgba(217, 66, 58, 0.7);
}
.aa-skill-applygap,
.aa-skill-applygap img {
  visibility: hidden;
  border-color: transparent;
  box-shadow: none;
}
.aa-skill-applytitle + .aa-skill-applyrow {
  margin-top: 0;
}
.aa-skill-applyrow + .aa-skill-applytitle {
  margin-top: 8px;
}
.aa-skill-applysub {
  display: block;
  margin: 0 0 2px 26px;
  color: #8a8478;
  font-size: 11px;
  line-height: 1.3;
}
.aa-skill-applyname {
  color: #e8e4d8;
}
.aa-skill-applyline {
  margin-left: auto;
  color: #a8a396;
  font-size: 11px;
}
/* duration, ticks, stacks in the box of an effect */
.aa-skill-fact {
  display: block;
  margin-top: 3px;
  color: #a8a396;
}
.aa-skill-bufftext + .aa-skill-fact {
  margin-top: 5px;
}
.aa-skill-buffname {
  display: block;
  margin-bottom: 3px;
  color: #ffffff;
  font-size: 13px;
  font-weight: bold;
}
.aa-skill-bufftext .aa-item-gap {
  margin-top: 0.5em;
}
/* red frame for a harmful effect (debuff) */
.aa-skill-debuff {
  border-color: #d9423a;
  box-shadow: 0 0 3px rgba(217, 66, 58, 0.7);
}
.aa-skill-desc {
  color: #e8e4d8;
}
.aa-skill-gap,
.aa-skill-desc .aa-item-gap {
  margin-top: 0.7em;
}

/* element (Quake, Life ...) and rank at the right of the header */
.aa-skill-tag {
  margin-left: auto;
  align-self: flex-start;
  text-align: right;
  line-height: 1.3;
}
.aa-skill-elem {
  color: #f5cb65;
  font-weight: bold;
}
/* the versions: the shown one in gold, the others dim; a click opens them */
.aa-skill-elem-alt {
  font-weight: normal;
}
.aa-skill-elem-alt a {
  color: #9b9484;
}
.aa-skill-elem-alt a:hover {
  color: #f5cb65;
}
/* combo: icons, then the sentence of the game */
.aa-skill-combo {
  display: flex;
  gap: 8px;
  align-items: center;
  margin-top: 4px;
}
.aa-skill-comboicons {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  flex: none;
  line-height: 0;
}
.aa-skill-comboicons img {
  display: block;
  border: 1px solid #000;
}
/* (not the icons inside the hover box of the icon: ":not(.aa-skill-bufftip)") */
.aa-skill-ico-bad > img,
.aa-skill-ico-bad > :not(.aa-skill-bufftip) img {
  border-color: #d9423a;
  box-shadow: 0 0 3px rgba(217, 66, 58, 0.7);
}
.aa-skill-ico-good > img,
.aa-skill-ico-good > :not(.aa-skill-bufftip) img {
  border-color: #4ec24e;
  box-shadow: 0 0 3px rgba(78, 194, 78, 0.6);
}
.aa-skill-combotext {
  color: #9acd32;
  line-height: 1.35;
}
.aa-skill-arrow {
  color: #8a8478;
  font-size: 14px;
  line-height: 1;
}
/* chain: the skills that follow each other, the one shown is outlined */
.aa-skill-chainlabel {
  margin: 10px 0 6px;
  text-align: center;
}
.aa-skill-chainlabel span {
  display: inline-block;
  padding: 1px 14px;
  border-radius: 10px;
  background: #7a1f1f;
  border: 1px solid #a33;
  color: #f3d9b0;
  font-size: 12px;
  font-weight: bold;
}
.aa-skill-chain {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 4px;
  max-width: 100%;
}
.aa-skill-chain .aa-skill-arrow {
  font-size: 14px;
  margin-bottom: 14px;
}
.aa-skill-step {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  color: #a8a396;
  font-size: 11px;
  line-height: 1.2;
}
.aa-skill-stepicon {
  display: block;
  line-height: 0;
  border: 1px solid #000;
}
.aa-skill-current .aa-skill-stepicon {
  box-shadow: 0 0 0 2px #ff9c27;
}
.aa-skill-current {
  color: #ff9c27;
}

/* Phones: a floated card gets its own line instead of squeezing the text */
@media (max-width: 500px) {
  .aa-skill-float {
    float: none !important;
    clear: both !important;
    margin: 0 0 0.5em 0 !important;
  }
  /* the effect box becomes a panel at the bottom of the screen (tap an icon to open) */
  .aa-skill .aa-skill-bufftip {
    position: fixed;
    left: 0.5em;
    right: 0.5em;
    top: auto;
    bottom: 0.5em;
    width: auto;
    max-height: 60vh;
    overflow-y: auto;
    margin-top: 0;
  }
}

.aa-skill-orange {
  color: #ff9c27;
}

/* the item that raises the rank of the skill (Fantasia of Sorcery): a switch in the header of the card */
.aa-skill-boost {
  position: relative;
  flex: none;
  align-self: flex-start;
  margin-left: auto;
  line-height: 0;
  cursor: pointer;
}
.aa-skill-boost img {
  display: block;
  border: 1px solid #000;
  opacity: 0.5;
  filter: grayscale(0.6);
}
.aa-skill-boost:hover img {
  opacity: 1;
  filter: none;
}
.aa-skill-boost-on img {
  opacity: 1;
  filter: none;
  box-shadow: 0 0 0 2px #ff9c27;
}
.aa-skill-boost .aa-skill-bufftip {
  left: auto;
  right: 0;
  width: 210px;
  line-height: 1.45;
}
.aa-skill-boost:hover .aa-skill-bufftip {
  display: block;
}
/* the switch sits left of the versions: they keep their place at the right edge */
.aa-skill-boost + .aa-skill-tag {
  margin-left: 8px;
}
.aa-skill-boost .aa-skill-bufftip {
  left: 0;
  right: auto;
}
